308	import net.officefloor.hq.app.sheet.SheetService;
309	import org.springframework.stereotype.Service;
310	import org.springframework.transaction.annotation.Transactional;
311	
312	/** The pools on a sheet: each a name and its members, people or other pools of the sheet, each with a
313	 *  share percent. */
314	@Service
315	public class PoolService {
316	
317	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
318	
319	    /** The most pools a chain of pools, each a member of the one above, may hold. */
320	    private static final int MAX_DEPTH = 3;
321	
322	    /** A pool with its members, in the order they were added. */
323	    public record PoolWithMembers(Pool pool, List<PoolMember> members) {
324	    }
325	
326	    private final PoolRepository pools;
327	    private final PoolMemberRepository members;
328	    private final PersonRepository people;
329	    private final SheetService sheets;
330	    private final Audit audit;
331	
332	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
333	            SheetService sheets, Audit audit) {
334	        this.pools = pools;
335	        this.members = members;
336	        this.people = people;
337	        this.sheets = sheets;
338	        this.audit = audit;
339	    }
340	
341	    /** The sheet's pools, in the order they were added, each with its members. */
342	    public List<PoolWithMembers> list(String sheetId) {
343	        List<Pool> list = pools.findBySheetIdOrderByIdAsc(sheetId);
344	        Map<Long, List<PoolMember>> byPool = members
345	                .findByPoolIdInOrderByIdAsc(list.stream().map(Pool::getId).toList()).stream()
346	                .collect(Collectors.groupingBy(PoolMember::getPoolId));
347	        return list.stream().map(p -> new PoolWithMembers(p, byPool.getOrDefault(p.getId(), List.of()))).toList();
348	    }
349	
350	    /** Add a pool, its name trimmed. Refused when the name is blank or already a pool's on the sheet.
351	     *  The sheet is held locked so the same name added at the same moment is checked against itself. */
352	    @Transactional
353	    public PoolWithMembers add(String sheetId, String user, String name) {
354	        String key = name == null ? "" : name.trim();
355	        if (key.isEmpty()) {
356	            throw new PoolRefusedException("A pool needs a name");
357	        }
358	        sheets.lock(sheetId);
359	        if (pools.existsBySheetIdAndName(sheetId, key)) {
360	            throw new PoolRefusedException("The pool " + key + " is on the sheet already");
361	        }
362	        Pool saved = pools.saveAndFlush(new Pool(sheetId, key));
363	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + key);
364	        return new PoolWithMembers(saved, List.of());
365	    }
366	
367	    /** Add a member to a pool with a share percent: more than 0.00 and at most 100.00, with up to two
368	     *  decimals, and an optional from-date and to-date, both included. The member is a person of the
369	     *  sheet, or another pool of the sheet (memberPoolId). Refused for such a share, a to-date before
370	     *  the from-date, a person already in the pool, a pool that is a member of a pool
371	     *  already, a pool that would contain itself through any chain, or a chain of pools more than
372	     *  three deep. */
373	    @Transactional
374	    public PoolWithMembers addMember(String sheetId, String user, Long poolId, Long personId, Long memberPoolId,
375	            BigDecimal share, LocalDate from, LocalDate to) {
376	        if (from != null && to != null && to.isBefore(from)) {
377	            throw new PoolRefusedException("A membership's to-date is not before its from-date");
378	        }
379	        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
380	                || share.stripTrailingZeros().scale() > 2) {
381	            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
382	        }
383	        if ((personId == null) == (memberPoolId == null)) {
384	            throw new PoolRefusedException("A member is a person or a pool");
385	        }
386	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
387	        sheets.lock(sheetId);
388	        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
389	                .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
390	        String name;
391	        if (personId != null) {
392	            Person person = people.findByIdAndSheetId(personId, sheetId)
393	                    .orElseThrow(() -> new PoolRefusedException("No such person on the sheet"));
394	            if (members.existsByPoolIdAndPersonId(poolId, personId)) {
395	                throw new PoolRefusedException(person.getName() + " is in the pool " + pool.getName() + " already");
396	            }
397	            members.saveAndFlush(new PoolMember(poolId, personId, scaled).dated(from, to));
398	            name = person.getName();
399	        } else {
400	            Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
401	                    .orElseThrow(() -> new PoolRefusedException("No such pool on the sheet"));
402	            checkNesting(sheetId, pool, member);
403	            members.saveAndFlush(PoolMember.ofPool(poolId, memberPoolId, scaled).dated(from, to));
404	            name = member.getName();
405	        }
406	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
407	                + " name=" + name + " share=" + scaled.toPlainString() + (from != null ? " from=" + from : "")
408	                + (to != null ? " to=" + to : ""));
409	        return new PoolWithMembers(pool, members.findByPoolIdInOrderByIdAsc(List.of(poolId)));
410	    }
411	
412	    /** Refuse making the pool member a member of the pool when it is a member of a pool already, when
413	     *  the pool is the member or lies inside it, or when the chain of pools would be more than three
414	     *  deep. */
415	    private void checkNesting(String sheetId, Pool pool, Pool member) {
416	        if (members.findByMemberPoolId(member.getId()).isPresent()) {
417	            throw new PoolRefusedException("The pool " + member.getName() + " is a member of a pool already");
418	        }
419	        Map<Long, Long> parentOf = new HashMap<>();
420	        Map<Long, List<Long>> childrenOf = new HashMap<>();
421	        List<Long> ids = pools.findBySheetIdOrderByIdAsc(sheetId).stream().map(Pool::getId).toList();
422	        for (PoolMember m : members.findByPoolIdInOrderByIdAsc(ids)) {
423	            if (m.getMemberPoolId() != null) {
424	                parentOf.put(m.getMemberPoolId(), m.getPoolId());
425	                childrenOf.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
426	            }
427	        }
428	        // The pools from the pool up to the top, the pool counted.
429	        int above = 0;
430	        for (Long at = pool.getId(); at != null; at = parentOf.get(at)) {
431	            if (at.equals(member.getId())) {
432	                throw new PoolRefusedException("The pool " + pool.getName() + " would contain itself");
433	            }
434	            above++;
435	        }
436	        if (above + height(member.getId(), childrenOf) > MAX_DEPTH) {
437	            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
438	        }
439	    }
440	
441	    /** The pools in the longest chain down from this pool, the pool counted. */
442	    private int height(Long poolId, Map<Long, List<Long>> childrenOf) {
443	        int below = 0;
444	        for (Long child : childrenOf.getOrDefault(poolId, List.of())) {
445	            below = Math.max(below, height(child, childrenOf));
446	        }
447	        return below + 1;
448	    }
449	}
