685	package net.officefloor.hq.app.crew;
686	
687	import java.util.List;
688	import java.util.Map;
689	import java.util.stream.Collectors;
690	import net.officefloor.hq.app.Audit;
691	import net.officefloor.hq.app.person.Person;
692	import net.officefloor.hq.app.person.PersonRepository;
693	import net.officefloor.hq.app.sheet.SheetService;
694	import org.springframework.stereotype.Service;
695	import org.springframework.transaction.annotation.Transactional;
696	
697	/** The crews on a sheet: each a name, a lead from the sheet's people and its members. */
698	@Service
699	public class CrewService {
700	
701	    /** A crew with its members, in the order they were added. */
702	    public record CrewWithMembers(Crew crew, List<CrewMember> members) {
703	    }
704	
705	    private final CrewRepository crews;
706	    private final CrewMemberRepository members;
707	    private final PersonRepository people;
708	    private final SheetService sheets;
709	    private final Audit audit;
710	
711	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
712	            SheetService sheets, Audit audit) {
713	        this.crews = crews;
714	        this.members = members;
715	        this.people = people;
716	        this.sheets = sheets;
717	        this.audit = audit;
718	    }
719	
720	    /** The sheet's crews, in the order they were added, each with its members. */
721	    public List<CrewWithMembers> list(String sheetId) {
722	        List<Crew> list = crews.findBySheetIdOrderByIdAsc(sheetId);
723	        Map<Long, List<CrewMember>> byCrew = members
724	                .findByCrewIdInOrderByIdAsc(list.stream().map(Crew::getId).toList()).stream()
725	                .collect(Collectors.groupingBy(CrewMember::getCrewId));
726	        return list.stream().map(c -> new CrewWithMembers(c, byCrew.getOrDefault(c.getId(), List.of()))).toList();
727	    }
728	
729	    /** Add a crew, its name trimmed, led by a person of the sheet. Refused when the name is blank or
730	     *  already a crew's on the sheet, or the lead is not a person of the sheet. The sheet is held
731	     *  locked so the same name added at the same moment is checked against itself. */
732	    @Transactional
733	    public CrewWithMembers add(String sheetId, String user, String name, Long leadId) {
734	        String key = name == null ? "" : name.trim();
735	        if (key.isEmpty()) {
736	            throw new CrewRefusedException("A crew needs a name");
737	        }
738	        if (leadId == null) {
739	            throw new CrewRefusedException("A crew needs a lead");
740	        }
741	        sheets.lock(sheetId);
742	        Person lead = people.findByIdAndSheetId(leadId, sheetId)
743	                .orElseThrow(() -> new CrewRefusedException("No such person on the sheet"));
744	        if (crews.existsBySheetIdAndName(sheetId, key)) {
745	            throw new CrewRefusedException("The crew " + key + " is on the sheet already");
746	        }
747	        Crew saved = crews.saveAndFlush(new Crew(sheetId, key, lead.getId()));
748	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + key + " lead="
749	                + lead.getName());
750	        return new CrewWithMembers(saved, List.of());
751	    }
752	
753	    /** Add a person of the sheet to a crew. Refused for the crew's lead or a person in it already. */
754	    @Transactional
755	    public CrewWithMembers addMember(String sheetId, String user, Long crewId, Long personId) {
756	        if (personId == null) {
757	            throw new CrewRefusedException("A member is a person");
758	        }
759	        sheets.lock(sheetId);
760	        Crew crew = crews.findByIdAndSheetId(crewId, sheetId)
761	                .orElseThrow(() -> new CrewRefusedException("No such crew on the sheet"));
762	        Person person = people.findByIdAndSheetId(personId, sheetId)
763	                .orElseThrow(() -> new CrewRefusedException("No such person on the sheet"));
764	        if (crew.getLeadId().equals(personId)) {
765	            throw new CrewRefusedException(person.getName() + " leads the crew " + crew.getName());
766	        }
767	        if (members.existsByCrewIdAndPersonId(crewId, personId)) {
768	            throw new CrewRefusedException(person.getName() + " is in the crew " + crew.getName() + " already");
769	        }
770	        members.saveAndFlush(new CrewMember(crewId, personId));
771	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
772	                + " name=" + person.getName());
773	        return new CrewWithMembers(crew, members.findByCrewIdInOrderByIdAsc(List.of(crewId)));
774	    }
775	
776	    /** Make the merged person's crews the other's: the crews they lead are led by the other instead
777	     *  (the other leaving those crews' members), and their memberships become the other's, dropped
778	     *  where the other leads the crew or is in it already. */
779	    @Transactional
780	    public void merge(Long fromId, Long intoId) {
781	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(fromId)) {
782	            crew.setLeadId(intoId);
783	            crews.saveAndFlush(crew);
784	            members.findByPersonIdOrderByIdAsc(intoId).stream().filter(m -> m.getCrewId().equals(crew.getId()))
785	                    .forEach(members::delete);
786	            members.flush();
787	        }
788	        for (CrewMember member : members.findByPersonIdOrderByIdAsc(fromId)) {
789	            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
790	            if (crew.getLeadId().equals(intoId) || members.existsByCrewIdAndPersonId(crew.getId(), intoId)) {
791	                members.delete(member);
792	                members.flush();
793	            } else {
794	                member.setPersonId(intoId);
795	                members.saveAndFlush(member);
796	            }
797	        }
798	    }
799	}
