export function crewDueCents(crew: Crew, people: ReadonlyMap<number, CrewPerson>): number {
  return [crew.leadId, ...crew.memberIds]
    .map((id) => people.get(id)?.due ?? null)
    .reduce<number>((sum, d) => sum + (d ?? 0), 0);
}

